def f(inp):
    h=len(inp); w=len(inp[0])
    # find 2x2 block of 2s
    bl=None
    for r in range(h-1):
        for c in range(w-1):
            if inp[r][c]==inp[r][c+1]==inp[r+1][c]==inp[r+1][c+1]==2:
                bl=(r,c)
    br,bc=bl
    out=[row[:] for row in inp]
    def opp(mr,mc):
        # marker diagonal from block corner; opposite corner marker
        dr=1 if mr>=br+1 else -1
        dc=1 if mc>=bc+1 else -1
        return (br+dr, bc+dc)
    for r in range(h):
        for c in range(w):
            if inp[r][c] not in (0,2):
                mr,mc,co=r,c,inp[r][c]
                dr=1 if mr>=br+1 else -1
                dc=1 if mc>=bc+1 else -1
                o=opp(mr,mc)
                oc=out[o[0]][o[1]]
                rr,cc=mr+dr,mc+dc
                while 0<=rr<h and 0<=cc<w:
                    out[rr][cc]=oc
                    rr+=dr; cc+=dc
    return out
