def f(inp):
    h,w=len(inp),len(inp[0])
    blks=[(r,c) for r in range(h-1) for c in range(w-1) if inp[r][c]==inp[r][c+1]==inp[r+1][c]==inp[r+1][c+1]==2]
    out=[row[:] for row in inp]
    for br,bc in blks:
        # four diagonal neighbors of block: TL,TR,BR,BL -> collect colors there
        pos=[(br-1,bc-1,'TL'),(br-1,bc+1,'TR'),(br+1,bc-1,'BL'),(br+1,bc+1,'BR')]
        colors={}
        for r,c,nm in pos:
            if 0<=r<h and 0<=c<w and inp[r][c]!=0 and inp[r][c]!=2: colors[nm]=inp[r][c]
        # rotate colors CCW by one: TL<-BR, TR<-TL, BL<-TR, BR<-BL
        ncolors={'TL':colors.get('BR'),'TR':colors.get('TL'),'BL':colors.get('TR'),'BR':colors.get('BL')}
        for nm,nc in ncolors.items():
            if nc is None: continue
            r,c=(br-1 if nm in('TL','TR') else br+1, bc-1 if nm in('TL','BL') else bc+1)
            dr=-1 if r<br else 1; dc=-1 if c<bc else 1
            rr,cc=r+dr,c+dc
            while 0<=rr<h and 0<=cc<w:
                if out[rr][cc] not in (0,2): break
                out[rr][cc]=nc
                rr+=dr; cc+=dc
    return out

