def f(inp,stop_at_block=False):
    h,w=len(inp),len(inp[0])
    blks=[(r,c) for r in range(h-1) for c in range(w-1) if inp[r][c]==inp[r][c+1]==inp[r+1][c]==inp[r+1][c+1]==2]
    out=[row[:] for row in inp]
    # first pass: adopt colors (global rotation by block)
    seg_colors=[]
    for br,bc in blks:
        mk={'TL':inp[br-1][bc-1],'TR':inp[br-1][bc+1],'BR':inp[br+1][bc-1],'BL':inp[br+1][bc+1]}
        # skip markers not in range
        good={k:v for k,v in mk.items() if 0<=br-1<h and 0<=bc-1<w and v not in (0,2)}
        seg_colors.append(good)
        # corner->inherited color (counterclockwise predecessor)
        inherit={'TL':good.get('BR'),'TR':good.get('TL'),'BL':good.get('TR'),'BR':good.get('BL')}
    # second: paint segments
    dirs={'TL':(-1,-1),'TR':(-1,1),'BL':(1,-1),'BR':(1,1)}
    pos={'TL':lambda b:(br-1,bc-1),'TR':lambda b:(br-1,bc+1),'BL':lambda b:(br+1,bc-1),'BR':lambda b:(br+1,bc+1)}
    seg_cells=defaultdict(list)  # (corner,blkidx)->list of (r,c,color)
    all_segs=[]
    for bi,(br,bc) in enumerate(blks):
        for cor,d_ in dirs.items():
            inc=seg_colors[bi].get(cor)
            if inc is None: continue
            r,c=pos[cor](blks[bi])
            rr,cc=r+d_[0],c+d_[1]
            cells=[]
            while 0<=rr<h and 0<=cc<w:
                if out[rr][cc]!=0: break
                cells.append((rr,cc,inc))
                rr+=d_[0]; cc+=d_[1]
            all_segs.append(cells)
    # order: blocks sorted; within a block, TL,TR,BL,BR - try several orders
    import itertools
    base=list(range(len(blks)))
    def apply(order):
        res=[row[:] for row in inp]
        ok=True
        for seg in all_segs:
            for rr,cc,col in seg:
                if not(0<=rr<h and 0<=cc<w) or res[rr][cc]!=0: ok=False;break
                res[rr][cc]=col
        return ok,res
    for perm_order in [range(len(blks))]:
        pass
    return all_segs, seg_colors, blks

